const incoming = $input.first().json;
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
return [{ json: { input: body } }];

const payload = $input.first().json;
const result = payload.data || payload;
const body = result.draft?.body || '';
const trace = result.trace || {};
const diagnostics = result.diagnostics || {};
const input = $node['Normalize input'].json.input || {};
const violations = Array.isArray(result.violations) ? result.violations : [];
return [{
  json: {
    input,
    result,
    body,
    trace,
    diagnostics,
    violations,
    qualityPass: body.length >= Number(input.minChars || 800) && violations.length === 0,
    saveRequest: {
      requestId: input.requestId,
      actor: input.actor || 'n8n-novel-factory',
      payload: {
        workId: input.workId,
        chapterId: input.chapterId,
        chapterNumber: input.chapterNumber,
        volumeNumber: input.volumeNumber || 1,
        title: input.title || input.topic,
        body,
        status: input.generationStatus || 'first_draft',
        createIfMissing: input.createIfMissing !== false,
        metadata: {
          source: 'n8n.novel-factory-generate-quality-publish',
          contentbaseAction: 'generate-chapter',
          trace,
          diagnostics,
          contractUsed: result.contractUsed || null,
          nextAllowedActions: result.nextAllowedActions || []
        }
      }
    }
  }
}];

const saved = $input.first().json;
const input = $node['Normalize input'].json.input || {};
const savedItem = saved.item && typeof saved.item === 'object' ? saved.item : {};
return [{
  json: {
    saved,
    publishRequest: {
      accountId: input.accountId,
      bookId: input.bookId,
      localWorkId: input.localWorkId || input.workId,
      chapterId: input.chapterId || savedItem.chapterId,
      chapterNumber: input.chapterNumber,
      dryRun: input.dryRun !== false,
      waitForCompletion: true,
      idempotencyKey: 'novel-factory:publish:' + input.workId + ':' + input.chapterNumber + ':' + $execution.id
    }
  }
}];
